import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { generated } from '../scripts/gen-demo.ts';

/**
 * The demo of the landing page.
 *
 * The demo is generated by the engine, so it cannot say something the engine
 * does not say. This test regenerates it and compares, so a demo that has
 * drifted from the engine fails the build.
 */

const root = resolve(import.meta.dirname, '..');

describe('the generated demo', () => {
  it('matches what the engine says today', () => {
    const onDisk = readFileSync(resolve(root, 'src/landing/generated.json'), 'utf8');
    const fresh = `${JSON.stringify(generated, null, 2)}\n`;
    expect(onDisk).toBe(fresh);
  });

  it('names a fix the engine gives', () => {
    expect(generated.joseph.fixTitle).toContain('off by exactly');
    expect(generated.joseph.fixTitle).toContain('K_t Q_t');
  });

  it('shows a counterexample the engine found', () => {
    const counterexample = generated.joseph.counterexample;
    expect(counterexample).not.toBeNull();
    // the defined symbols are computed, not sampled
    expect(Object.keys(counterexample!.values)).not.toContain('\\Sigma_t');
    expect(Object.keys(counterexample!.derived)).toContain('\\Sigma_t');
    // and the numbers are small enough to read
    for (const value of Object.values(counterexample!.values)) {
      const numbers = Array.isArray(value) ? value : [value];
      for (const number of numbers) {
        expect(Math.abs(number)).toBeLessThan(100);
      }
    }
  });
});
